// Generates src/export-bundle-source.js from the v11 runtime module set.
//
// export-bundle-source.js embeds the runtime modules as strings so every
// exported inscription HTML is fully self-contained (artwork, flight,
// signature call, motion rig, verifiable audio fingerprint). Because it is
// generated from the live src files, the exported inscriptions automatically
// inherit v11's accessible core (keyboard + reduced-motion handling, C1).
//
// Usage:  node tools/build-export-bundle.mjs
// Requires cicada-renderer.js to be present (run scaffold-from-v10.mjs first
// if you have not copied it over yet).
import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const here = dirname(fileURLToPath(import.meta.url));
const SRC = join(here, '..', 'src');

// The modules an inscription needs at runtime (cicada-core.js + its transitive
// deps). Builder-only modules (builder-ui, trait-lab, sound-identity-ui,
// trait-registry, zip-utils) are intentionally excluded.
const RUNTIME_MODULES = [
    'config.js',
    'utils.js',
    'ground-gait.js',
    'sound-identity.js',
    'cicada-traits.js',
    'cicada-renderer.js',
    'cicada-nymph-renderer.js',
    'cicada-audio.js',
    'motion-bridge.js',
    'group-chorus.js',
    'cicada-core.js'
];

const missing = RUNTIME_MODULES.filter(name => !existsSync(join(SRC, name)));
if (missing.length) {
    console.error('Cannot build export bundle, missing src modules:', missing.join(', '));
    console.error('Run `node tools/scaffold-from-v10.mjs` first to copy cicada-renderer.js from the v10.4.0 sibling.');
    process.exit(1);
}

const entries = RUNTIME_MODULES.map(name => {
    const source = readFileSync(join(SRC, name), 'utf8');
    // JSON.stringify yields a safe double-quoted JS string literal, so embedded
    // backticks / ${ } / newlines in the module source cannot break the bundle.
    return `    ${JSON.stringify(name)}: ${JSON.stringify(source)}`;
}).join(',\n');

const out = `// AUTO-GENERATED by tools/build-export-bundle.mjs — do not edit by hand.
// Embeds the v11 runtime module set so each exported inscription HTML is
// self-contained. Regenerate after changing any runtime module.
export const EXPORT_MODULE_SOURCES = {
${entries}
};
`;

const target = join(SRC, 'export-bundle-source.js');
writeFileSync(target, out);
console.log(`Wrote ${target}`);
console.log(`  ${RUNTIME_MODULES.length} runtime modules, ${out.length.toLocaleString()} bytes.`);
